namespace scratchbird::engine::sblr{namespace{void p(std::vector<uint8_t>&o,uint64_t v,int n){for(int i=0;i<n;i++)o.push_back(v>>(8*i));}uint64_t g(const uint8_t*b,int n){uint64_t v=0;for(int i=0;i<n;i++)v|=uint64_t(b[i])<<(8*i);return v;}bool nz(const auto&a){return std::any_of(a.begin(),a.end(),[](uint8_t x){return x;});}bool h(const uint8_t*b,size_t n,const char*m,size_t z){return b&&n==z&&!memcmp(b,m,4)&&g(b+4,2)==1&&g(b+6,2)==z&&g(b+8,4)==z&&!g(b+12,4);}auto sh(const char*d,const uint8_t*b,size_t n){std::vector<uint8_t>x(d,d+strlen(d));x.insert(x.end(),b,b+n);return scratchbird::core::hash::ComputeSha256Digest(x).digest;}std::vector<uint8_t>hd(const char*m,size_t z){std::vector<uint8_t>o(m,m+4);p(o,1,2);p(o,z,2);p(o,z,4);p(o,0,4);return o;}}
std::vector<uint8_t>EncodeSblrUpdateRequestV1(const SblrUpdateRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.update_occurrence)return{};auto o=hd("UPDR",64);o.insert(o.end(),v.receipt.begin(),v.receipt.end());p(o,v.occurrence,8);p(o,v.update_occurrence,4);o.insert(o.end(),20,0);return o;}bool DecodeSblrUpdateRequestV1(const uint8_t*b,size_t n,SblrUpdateRequestV1*out,std::string*d){if(!out||!h(b,n,"UPDR",64)){if(d)*d="UPDR invalid";return false;}SblrUpdateRequestV1 v;std::copy_n(b+16,16,v.receipt.begin());v.occurrence=g(b+32,8);v.update_occurrence=g(b+40,4);if(std::any_of(b+44,b+64,[](uint8_t x){return x;})||EncodeSblrUpdateRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrUpdateDescriptorV1(const SblrUpdateDescriptorV1&v,bool op){if(!nz(v.canonical_body)||!v.availability_generation)return{};auto o=hd(op?"UPDO":"UPDD",456);o.insert(o.end(),v.canonical_body.begin(),v.canonical_body.end());auto e=sh("ScratchBird.SblrUpdateDescriptor.V1",o.data()+16,400);if(nz(v.evidence)&&v.evidence!=e)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability_generation,8);return o;}bool DecodeSblrUpdateDescriptorV1(const uint8_t*b,size_t n,SblrUpdateDescriptorV1*out,std::string*d,bool op){if(!out||!h(b,n,op?"UPDO":"UPDD",456)){if(d)*d="update descriptor invalid";return false;}SblrUpdateDescriptorV1 v;std::copy_n(b+16,400,v.canonical_body.begin());std::copy_n(b+416,32,v.evidence.begin());v.availability_generation=g(b+448,8);if(EncodeSblrUpdateDescriptorV1(v,op).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrUpdateResultV1(const SblrUpdateResultV1&v){if(!nz(v.canonical_body)||!v.availability_generation)return{};auto o=hd("UPRS",192);o.insert(o.end(),v.canonical_body.begin(),v.canonical_body.end());auto e=sh("ScratchBird.SblrUpdateResult.V1",o.data()+16,136);if(nz(v.evidence)&&v.evidence!=e)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability_generation,8);return o;}bool DecodeSblrUpdateResultV1(const uint8_t*b,size_t n,SblrUpdateResultV1*out,std::string*d){if(!out||!h(b,n,"UPRS",192)){if(d)*d="update result invalid";return false;}SblrUpdateResultV1 v;std::copy_n(b+16,136,v.canonical_body.begin());std::copy_n(b+152,32,v.evidence.begin());v.availability_generation=g(b+184,8);if(EncodeSblrUpdateResultV1(v).empty())return false;*out=v;return true;}}
